  <?php if (!$messages): ?><div class="tm-empty"><h3>No messages available</h3><p>No customer conversation has been linked to this ticket.</p></div><?php endif; ?>
  <ol class="tm-timeline"><?php foreach ($messages as $message): ?><li><article class="tm-message">
